import{_ as t,C as c,o as a,c as d,E as i,ax as n}from"./chunks/framework.b1umHdsy.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{"languageLink":"/_en/object/"},"headers":[],"relativePath":"object/index.md","filePath":"object/README.md"}'),p={name:"object/index.md"};function r(s,e,l,_,m,b){const o=c("objectTemp");return a(),d("div",null,[i(o),e[0]||(e[0]=n('<h2 id="概念解释" tabindex="-1">概念解释 <a class="header-anchor" href="#概念解释" aria-label="Permalink to &quot;概念解释&quot;">​</a></h2><p><code>object-fit</code> 和 <code>object-position</code> 可以类比为 <code>background-size</code> 和 <code>background-position</code></p><p>两个属性仅作用于替换元素</p><p>替换元素是指</p><blockquote><p>其内容不受 CSS 视觉格式化模型（中文释义参见这里）控制的元素，比如image, 嵌入的文档(iframe之类)或者applet。比如，img元素的内容通常会被其src属性指定的图像替换掉。替换元素通常有其固有的尺寸：一个固有的宽度，一个固有的高度和一个固有的比率。比如一幅位图有固有用绝对单位指定的宽度和高度，从而也有固有的宽高比率。另一方面，其他文档也可能没有固有的尺寸，比如一个空白的html文档。</p><p>CSS 渲染模型不考虑替换元素内容的渲染。这些替换元素的展现独立于CSS。object, video, textarea, input也是替换元素，audio和canvas在某些特定情形下为替换元素。</p><p>使用 CSS 的content属性插入的对象是匿名替换元素。</p></blockquote><p>也就是说，<code>img</code> 和 <code>form</code>表单控件， 以及 <code>video</code> 等元素即是替换元素，可以被 <code>object-fit</code> 和 <code>object-position</code> 属性所控制。</p><h2 id="适用" tabindex="-1">适用 <a class="header-anchor" href="#适用" aria-label="Permalink to &quot;适用&quot;">​</a></h2><p>对于容器固定而图片尺寸不确定，或者需要响应式布局时，图片固定而容器宽度不确定，需要等比例展示图片或视频。</p><div class="danger custom-block"><p class="custom-block-title">DANGER</p><p>IE 全版本不支持，edge16+ 支持，PC慎用</p></div>',9))])}const h=t(p,[["render",r]]);export{f as __pageData,h as default};
